entries[77800] = { ["name"] = "Fokussierte Einsicht", ["text"] = "Sofort\nNach dem Wirken eines Schockzaubers werden die Manakosten Eurer nächsten Heilung um einen Prozentsatz der Kosten des Schockzaubers verringert und die Heilwirkung erhöht.\nModifies Power Cost 0:\nErdbeben , Große Welle der Heilung , Heilende Woge , Heilender Regen , Kettenheilung , Springflut , Welle der Heilung\n\nModifies Damage/Healing Done 0%:\nErdbeben , Große Welle der Heilung , Heilende Woge , Kettenheilung , Springflut , Welle der Heilung\n\nModifies Periodic Damage/Healing Done 0%:\nSpringflut" }
entries[77801] = { ["name"] = "Dämonenseele", ["text"] = "15% von Grundmana 100 Meter Reichweite\nSofort 2 min Abklingzeit\nIhr verschmelzt Eure Seele mit der Eures beschworenen Dämons, wodurch Ihr zeitweise Kräfte gewinnt, die vom beschworenen Dämon abhängig sind.\n\nWichtel - Die kritische Trefferchance von Zerstörungszaubern mit Zauberzeit wird 20 Sek. lang um 30% erhöht.\n\nLeerwandler - Jegliche von Euch erzeugte Bedrohung wird 15 Sek. lang auf Euren Leerwandler umgelenkt.\n\nSukkubus - Der verursachte Schaden von 'Schattenblitz' wird 20 Sek. lang um 10% erhöht.\n\nTeufelsjäger - Euer regelmäßiger Schattenschaden wird 20 Sek. lang um 20% erhöht.\n\nTeufelswache - Das Zaubertempo wird um 15%, der verursachte Feuer- und Schattenschaden um 10% erhöht. Hält 20 Sek. lang an." }
